//! The policy component, linked by the runtime itself.
//!
//! `enclave:signer` is wired by hand in `signer::add_to_linker`, and the guest's imports are
//! generated by wit-bindgen from the runtime's own `wit/` (the `enclave-wit` crate). wasmtime checks every import's name and type
//! when it links a component, so an enclave that starts on `policy.wasm` is one whose wiring
//! matches what the guest calls. What the calls do is `wallet`'s unit tests'.
//!
//! ```console
//! $ nix build .#policy
//! $ POLICY_WASM=result/bin/policy.wasm cargo test -p enclave-runtime --test policy -- --ignored
//! ```

use enclave_runtime::testing::Enclave;

fn guest() -> Vec<u8> {
    let path = std::env::var_os("POLICY_WASM")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| {
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../result/bin/policy.wasm")
        });
    std::fs::read(&path).unwrap_or_else(|e| {
        panic!(
            "{}: {e}; build it with `nix build .#policy`",
            path.display()
        )
    })
}

#[tokio::test]
#[ignore = "needs policy.wasm: nix build .#policy"]
async fn the_policy_guest_links_against_the_runtime() {
    Enclave::builder(guest())
        .background_tasks()
        .start()
        .await
        .expect("the runtime links every import the policy guest makes");
}
